<?php declare(strict_types=1); use Core\Http\Router; use Modules\Users\Controllers\UserController; return function (Router $router): void { $router->group([ 'prefix' => 'admin/users', 'middleware' => ['web', 'auth'], 'name' => 'admin.users.', ], function (Router $router): void { $router->get('/', [UserController::class, 'index']) ->middleware('permission:users.manage') ->name('index'); $router->get('/create', [UserController::class, 'create']) ->middleware('permission:users.manage') ->name('create'); $router->post('/', [UserController::class, 'store']) ->middleware('permission:users.manage') ->name('store'); $router->get('/{id}/edit', [UserController::class, 'edit']) ->middleware('permission:users.manage') ->where('id', '\d+') ->name('edit'); $router->post('/{id}', [UserController::class, 'update']) ->middleware('permission:users.manage') ->where('id', '\d+') ->name('update'); $router->post('/{id}/delete', [UserController::class, 'destroy']) ->middleware('permission:users.manage') ->where('id', '\d+') ->name('destroy'); }); }; 